+// parkPageBuildFailure files the strike-3 escalation. RAW insert, deliberately NOT
+// insertWorkItem — see the two-strike note above — arbitrated by idx_swi_dedup via
+// bare ON CONFLICT DO NOTHING, exactly like emitOwnedPageReviewItem. Holding
+// item_key 'needs_page:<name>' OPEN at needs_human_review blocks ReconcileSitePlanAction's
+// raw INSERT, WriteBuildItemsAction's keyed insert, and tool-recreation's items for
+// this page slot until a human closes it; closePageBuildFailureItems reopens the
+// slot automatically when any later deploy stamp succeeds.
+func parkPageBuildFailure(ctx context.Context, db *sql.DB, siteID, pageID uuid.UUID, pageName, skipReason string, strikes int, logger *zap.Logger) {
+	spec, _ := json.Marshal(map[string]interface{}{"page_name": pageName, "page_id": pageID.String(), "skip_reason": skipReason, "refusals": strikes, "fix": "Content generation for this page failed " + fmt.Sprint(strikes) + " times; automatic rebuilds are parked. Fix the cause (spec, quota, component), then close this item — the next successful deploy also closes it automatically."})
+	if _, err := db.ExecContext(ctx, `INSERT INTO site_work_items (site_id, source, pipeline, item_type, severity, summary, spec, page_id, priority, status, created_by, item_key) VALUES ($1, 'update_page_status', 'build', 'page_build_failed', 'high', $2, $3::jsonb, $4, 40, 'needs_human_review', 'update_page_status', $5) ON CONFLICT DO NOTHING`, siteID, fmt.Sprintf("Page %s: content generation failed %d times — rebuild parked for a human", pageName, strikes), string(spec), pageID, "needs_page:"+pageName); err != nil { logger.Warn("parkPageBuildFailure: park insert failed", zap.Error(err)) }
+}
+
+// closePageBuildFailureItems completes any open park for the page after a
+// successful deploy stamp — success is the definitive evidence the parked
+// condition is resolved, and an open park would otherwise outlive its truth AND
+// keep blocking the page's slot.
+func closePageBuildFailureItems(ctx context.Context, db *sql.DB, pageID uuid.UUID, logger *zap.Logger) {
+	if _, err := db.ExecContext(ctx, `UPDATE site_work_items SET status = 'complete', updated_at = NOW() WHERE item_type = 'page_build_failed' AND page_id = $1 AND status = 'needs_human_review'`, pageID); err != nil { logger.Warn("closePageBuildFailureItems failed", zap.Error(err)) }
+}

